@startuml

class Employee {
  + Name : string
  + Ssn : int
}

class CreativeEmployee extends Employee {
  + OscarWinner : boolean
}

class Director extends CreativeEmployee {
  + AssistantName : string
}

class Actor extends CreativeEmployee {
  + Education : string
}

class Technician extends Employee {
  + FieldOfActivity : string
}

class Location {
  + Name : string
}

class Film {
  + Title : string
  + ReleaseYear : int
}

class Genre {
  + Type : string
}

class Screenwriter {
  + Name : string
  + MostSuccessfulFilm : string
}

class Screenplay {
  + Title : string
  + Version : string
  + Date : date
  + NumberOfScenes : int
  + Plot : string
}

class Novel {
  + Title : string
  + Author : string
}

class Concept {
}

Film "*" -- "*" Location : shot_at
Film "*" -- "1" Genre : assigned_to
Film "1" -- "1" Screenplay : based_on
Film "1" -- "1" Director : directed_by
Film "*" -- "*" Actor : features
Actor "*" -- "1" Screenplay : reads_for_role
Screenplay "1" -- "1" Screenwriter : written_by
Screenplay "*" -- "0..1" Novel : based_on
Screenplay "*" -- "0..1" Concept : based_on

@enduml

